<?php require_once __DIR__.'/lib/auth.php';requireAuth();require_once __DIR__.'/config/database.php';if(!hash_equals($_SESSION['drive_oauth_state']??'',$_GET['state']??'')||empty($_GET['code'])){http_response_code(400);exit('Invalid OAuth response.');}$redirect='http://127.0.0.1:8001/drive_callback.php';$post=http_build_query(['code'=>$_GET['code'],'client_id'=>getenv('GOOGLE_CLIENT_ID'),'client_secret'=>getenv('GOOGLE_CLIENT_SECRET'),'redirect_uri'=>$redirect,'grant_type'=>'authorization_code']);$ch=curl_init('https://oauth2.googleapis.com/token');curl_setopt_array($ch,[CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>$post,CURLOPT_RETURNTRANSFER=>true,CURLOPT_HTTPHEADER=>['Content-Type: application/x-www-form-urlencoded']]);$raw=curl_exec($ch);$token=json_decode((string)$raw,true);if(empty($token['access_token'])){http_response_code(502);exit('Drive token exchange failed.');}$key=hash('sha256',(string)getenv('RESUMEIQ_APP_KEY'),true);$iv=random_bytes(12);$tag='';$cipher=openssl_encrypt(json_encode($token),'aes-256-gcm',$key,OPENSSL_RAW_DATA,$iv,$tag);$payload=base64_encode($iv.$tag.$cipher);db()->prepare("INSERT INTO integrations(provider,status,config_json) VALUES('google_drive','connected',?) ON DUPLICATE KEY UPDATE status='connected',config_json=VALUES(config_json)")->execute([json_encode(['encrypted_token'=>$payload])]);unset($_SESSION['drive_oauth_state']);header('Location: integrations.php?connected=1');
